using namespace std;

int main() {
    int l;
    string n;
    cin >> l >> n;

    const string target = "ACTG";
    int res = INT_MAX;

    for (int i = 0; i + 3 < l; ++i) {
        int moves = 0;
        for (int j = 0; j < 4; ++j) {
            int diff = abs(n[i + j] - target[j]);
            moves += min(diff, 26 - diff);
        }
        res = min(res, moves);
    }

    cout << res << '\n';
    return 0;
}

